  "bin": {
    "scarwise": "dist/cli.mjs"
  },
  "exports": {
    "./sdk": "./dist/sdk.mjs"
  },
  "scripts": {
    "postinstall": "node dist/cli.mjs init --postinstall || exit 0"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=22.18"
  },
  "license": "SEE LICENSE IN LICENSE",
  "homepage": "https://github.com/DomitorAI/scarwise#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DomitorAI/scarwise.git"
  },
  "bugs": {
    "url": "https://github.com/DomitorAI/scarwise/issues"
  },
  "author": "DomitorAI (https://github.com/DomitorAI)",
  "keywords": [
    "ai",
    "ai-agents",
    "mcp",
    "model-context-protocol",
    "claude-code",
    "codex",
    "gemini-cli",
    "cursor",
    "copilot",
    "opencode",
    "qwen-code",
